"use strict";
// A self-contained fictional handset story. No real messages, accounts or history.
const tideStoreKey='olddays-tide-v1';
const tideDevices={silver:{model:'symbian',date:'2004-09-12',title:'银色 6600',source:'旧货摊买来，电池后盖贴着一张乐队贴纸。',owner:'阿禾'},black:{model:'n73',date:'2008-10-19',title:'黑色 N73',source:'维修店清理旧箱时收来的。存储卡还在，没人留下姓名。',owner:'未登记'},white:{model:'nokia5230',date:'2010-06-06',title:'白色 5230',source:'表姐换机送的，屏幕右下角有一道细裂纹。',owner:'林恬'}};
let tide={active:false,device:'black',seen:[],replied:false,solved:false,ending:'',notes:'',notebooks:{silver:'',black:'',white:''},draft:'',quiet:true,conversations:{silver:[],black:[],white:[]}},tideView='',tideFeedback='',tideResetArmed=false;
try{const p=JSON.parse(localStorage.getItem(tideStoreKey)||'null');if(p){tide.active=p.active===true;tide.device=Object.hasOwn(tideDevices,p.device)?p.device:'black';tide.seen=['sms','qq','pier','gate','window','back','forum','timetable','recording'].filter(k=>p.seen?.includes(k));tide.replied=p.replied===true;tide.solved=p.solved===true&&['qq','gate','back','forum','timetable','recording'].every(k=>tide.seen.includes(k));tide.ending=tide.solved&&['sealed','played'].includes(p.ending)?p.ending:'';tide.notes=typeof p.notes==='string'?p.notes.slice(0,1200):'';for(const id of Object.keys(tideDevices))tide.notebooks[id]=typeof p.notebooks?.[id]==='string'?p.notebooks[id].slice(0,1200):'';tide.notebooks[tide.device]=tide.notes;tide.draft=typeof p.draft==='string'?p.draft.slice(0,100):'';tide.quiet=p.quiet!==false;}}catch{}
const tideChatChoices={
 silver:[['practice','问排练时间','周六几点去老琴房？','老杜：下午两点。阿禾，你把那根接触不好的线也带来，先别急着买新的。'],['song','问没写完的歌','那首歌的副歌还留着吗？','老杜：留着呢，文件叫《下雨以前》。你先把贝斯接好，名字可以演完再想。'],['bus','聊末班车','演出结束还能赶上车吗？','老杜：别又只顾着收线。十一点末班，十点半我叫你。']],
 white:[['photo','问合照','合照背后的字，大家都写了吗？','同桌：写啦。你说要留到十年以后再看，可别把原图弄丢了。'],['print','聊洗照片','多洗两张给外婆好吗？','同桌：当然。林恬你挑一张大家都没闭眼的，我把原图拷给你。'],['summer','聊暑假','暑假还回来拍照吗？','同桌：回来呀。别只拍我们，也给自己留一张。']],
 black:[['reader','问读卡器','读卡器还在阿北那里吗？','阿巡的离线自动回复：白天做实验，晚上再看消息。阿北说读卡器已放回你桌上。'],['file','询问声音文件','你听过那份右声道文件吗？','阿巡的离线留言：我只听了你发的短段，不能替你确定声音来源。你常去的那个器材版有人在讨论串音。'],['wait','先留一句话','等你上线再说，先不转发。','留言已留在本机待发列表。对方离线，尚未收到。']]
};
function tideChatReply(id){const choice=tideChatChoices[tide.device]?.find(x=>x[0]===id);if(!choice)return false;const history=tide.conversations[tide.device];if(!history.includes(id)){history.push(id);tideSave();}return true;}
function tideChatMarkup(){const choices=tideChatChoices[tide.device],history=tide.conversations[tide.device];return `<section class="tide-conversation"><small>${tide.device==='black'?'离线记录与待发留言 · 本机模拟':'保存在这部手机上的对话 · 本机模拟'}</small>${history.map(id=>{const c=choices.find(x=>x[0]===id);return `<article><p class="tide-chat-me">我：${escapeHTML(c[2])}</p><p>${escapeHTML(c[3])}</p></article>`;}).join('')}<nav class="tide-chat-choices" aria-label="选择聊天回复">${choices.map(c=>`<button data-tide-reply="${c[0]}" ${history.includes(c[0])?'disabled':''}>${history.includes(c[0])?'已聊过 · ':''}${c[1]}</button>`).join('')}</nav></section>`;}
try{const p=JSON.parse(localStorage.getItem(tideStoreKey)||'null');for(const id of Object.keys(tideDevices)){if(Array.isArray(p?.conversations?.[id]))tide.conversations[id]=[...new Set(p.conversations[id].filter(x=>tideChatChoices[id].some(c=>c[0]===x)))].slice(0,3);}}catch{}
function tideSave(){try{localStorage.setItem(tideStoreKey,JSON.stringify(tide));}catch{toast('存档暂时不可用，请保留此页面');}}
function tideMark(key){if(tide.device!=='black'||!['sms','qq','pier','gate','window','back','forum','timetable','recording'].includes(key))return; if(!tide.seen.includes(key)){tide.seen.push(key);tideSave();}}
function tideStage(){return tide.solved?3:tide.seen.includes('recording')&&tide.seen.includes('gate')&&tide.seen.includes('forum')?2:tide.seen.length>=3?1:0;}
function tideBtn(view,label){return `<button data-tide-view="${view}">${label}</button>`;}
function tideFrame(title,body){return `<section class="tide-app tide-${tide.device}" data-story-stage="${tideStage()}"><header><span>${escapeHTML(title)}</span><small>${tide.device==='black'?'18 / 10 / 2008':'个人文件'}</small></header>${body}<footer>${tideBtn('shelf','收藏架')}${tideBtn('journal','随手记')}${tideBtn('native','退出故事，普通游玩')}</footer></section>`;}
function tideShelf(){return `<section class="tide-shelf"><small>原创手机探索故事 / 潮声收藏者</small><h2>你收来的旧手机</h2><p>你在读大学，闲下来会修一修、收几部旧手机。有些只是听歌打游戏的小东西，有些还留着前一个人的生活。</p><p>今晚雨很大。桌上的三块电池，总算都充进了电。</p><div>${Object.entries(tideDevices).map(([id,d])=>`<button data-tide-device="${id}"><b>${d.title}</b><small>${d.date.slice(0,4)} 年的内容</small><span>${d.source}</span><em>开机 ›</em></button>`).join('')}</div><details><summary>游玩说明与内容提示</summary><p>包含缓慢出现的怪谈元素，无突然巨响。消息、人物、网页、海边场景和潮汐数据均为原创虚构；不读取真实聊天或浏览记录。图像为故事重绘，不是历史实拍。声音仅手动播放，可保持静音。游戏音乐等原有功能可随时使用。独立手机各有不同内容，黑色手机包含本篇完整故事。</p></details><button data-tide-leave>返回设备馆</button></section>`;}
function tideHome(){return tideFrame('待机',`<div class="tide-standby"><b>${tide.device==='black'?'23:41':'20:04'}</b><span>${tide.device==='black'?'无名录音集':tideDevices[tide.device].owner}</span><p>${tide.device==='black'?(tideStage()>=2?'未读信息 (1)':'存储卡已插入'):'中国移动'}</p></div><nav class="tide-app-grid phone-home-grid">${[['sms','✉','信息'],['qq','QQ','QQ'],['photos','▧','相册'],['browser','网','浏览器'],['community','坛','论坛'],['music','♫','音乐'],['games','✣','游戏'],['books','书','小说']].map(([app,icon,label])=>`<button class="system-app" data-phone-app="${app}"><b>${icon}</b><span>${label}</span></button>`).join('')}</nav>`);}
const tideMessages=[['妈','10-16 18:21','饭留锅里了。小舟，录声音归录声音，别总等到没车才回。'],['阿巡','10-17 22:06','你上次发我的那个不是鸟叫。左耳一直有敲铁门的声音，你录的时候没听见？'],['10086','10-18 09:00','本月剩余流量 8.4MB。夜间套餐将于月底到期。'],['草稿','10-18 03:39','我已经回到房间了。外面不是海。']];
function tideSms(){if(tide.device!=='black'){const silver=tide.device==='silver';return tideFrame('信息',`<article><b>${silver?'老杜 · 2004-09-11':'妈妈 · 2010-06-05'}</b><p>${silver?'排练改周六。阿禾记得带转接头，鼓手那台MP3又只能响一边了。':'林恬，毕业合照洗好了，回家时带两张给外婆。'}</p></article><article><b>草稿</b><p>${silver?'曲子还没写完，先把副歌存着。':'照片背后的字要不要留？还是留着吧。'}</p></article>`);}
if(tideView.startsWith('sms:')){const i=Number(tideView.split(':')[1]),m=tideMessages[i];if(!m)return tideHome();tideMark('sms');return tideFrame(m[0],`<article><small>${m[1]}</small><p>${m[2]}</p></article>${tideBtn('sms','返回收件箱')}`);}
return tideFrame('信息 / 收件箱',`<div class="tide-list">${tideMessages.map((m,i)=>tideBtn('sms:'+i,`${m[0]}　${m[1]}　${m[2].slice(0,18)}…`)).join('')}${tideStage()>=1?'<article><b>未知号码 · 刚刚</b><p>那一份不要再往外传了。我找不到原来的帖子。</p></article>':''}${tideStage()>=2?`<article class="tide-wrong"><b>本机号码 · 03:17</b><p>${tide.replied&&tide.draft?'“'+escapeHTML(tide.draft)+'”':'房间里那扇门，也会生锈吗？'}</p><small>发件箱里没有这条记录。</small></article>`:''}</div><form data-tide-compose><label>写一条本机留言<textarea name="message" maxlength="100" aria-label="潮声手机留言" placeholder="信号很弱，先写在这里…">${escapeHTML(tide.draft)}</textarea></label><button>存入发件箱</button></form>${tide.replied?'<small>发送失败，文字留在本机草稿。</small>':''}`);}
function tideQQ(){if(tide.device!=='black')return tideFrame('QQ / 离线消息',`<article><b>${tide.device==='silver'?'老杜':'林恬的同桌'}</b><p>${tide.device==='silver'?'周六还是老琴房，阿禾的贝斯先放我这。':'你给全班拍的那组照片真好看。我们每年都回来拍一张吧。'}</p></article>${tideChatMarkup()}`);
if(tideView==='qq:chat'){tideMark('qq');return tideFrame('QQ / 阿巡 [离线]',`<article><small>10月17日　22:04</small><p>许舟，你该不会又去收海浪声了吧？</p><p>你说鸟叫有季节，浪声没有。但上次那段里，有人敲了三下。你总说录音后面还有一句，得把右声道单独放出来。</p><small>10月18日　10:16</small><p>你在“回声采集”发的东西被删了？我点你空间里的链接，只剩404。没有现场照片我也分不清那是灯塔还是堤下。</p></article>${tideChatMarkup()}${tideBtn('qq','返回好友')}`);}
return tideFrame('QQ 2008',`<article><b>听潮的人</b><p>签名：只留下声音，不留下脚印。</p></article>${tideBtn('qq:chat','阿巡　[离线消息]')}${tideBtn('qq:ordinary','阿北　[同学]')}${tideView==='qq:ordinary'?'<article><p>明天记得交实验报告。上次你借的读卡器放我桌上就行。</p></article>':''}`);}
const tideLifePhotos={
 silver:[{file:'night',name:'排练以后.JPG',time:'2004-09-04 22:18',alt:'夜色与灯光的怀旧配图',front:'散场以后，耳朵里还响着那段没弹齐的副歌。',back:'老杜在背面写：先别删，第一次合奏只有这张纪念。'},
 {file:'campus',name:'老琴房门口.JPG',time:'2004-09-11 13:42',alt:'校园小路的怀旧配图',front:'到早了。琴房还没开门，先在外面等一会儿。',back:'阿禾：带了备用线，忘了带午饭。演出不一定成功，饭一定要吃。'}],
 white:[{file:'campus',name:'毕业的夏天.JPG',time:'2010-06-05 16:20',alt:'校园树影的怀旧配图',front:'林恬：毕业的夏天。下次大家还站在这里。',back:'给外婆留两张。照片里的路还在，人不能一直站着不走。'},
 {file:'portrait',name:'练习人像.JPG',time:'2010-06-04 15:08',alt:'原创人像摄影风格配图',front:'摄影社的练习：别总让被拍的人看镜头，也拍拍发呆的时候。',back:'同桌：这张光线最好。林恬你下次也站进去，我来按快门。'}]
};
function tideLifeAlbum(){const photos=tideLifePhotos[tide.device];if(!photos)return tideHome();const match=/^life(photo|back|meta):(\d+)$/.exec(tideView),index=match?Number(match[2]):-1,p=photos[index];
 if(p){const content=match[1]==='back'?`<article class="tide-photo-back"><p>${escapeHTML(p.back)}</p></article>${tideBtn('lifephoto:'+index,'翻回照片')}`:match[1]==='meta'?`<article><p>${escapeHTML(p.name)}</p><p>${p.time}</p><p>这部手机的本机相册 / 原创虚构生活记录</p><small>时间为故事设定，配图为本站怀旧创作，并非人物实拍或原始 EXIF。</small></article>${tideBtn('lifephoto:'+index,'返回照片')}`:`<figure class="tide-photo"><img src="images/memories/${p.file}.jpg" alt="${p.alt}"></figure><p>${escapeHTML(p.front)}</p><div class="tide-photo-tools"><button data-tide-zoom>放大 / 还原</button>${tideBtn('lifeback:'+index,'照片背面')}${tideBtn('lifemeta:'+index,'文件信息')}</div>`;
 return tideFrame(p.name,content+`<nav class="tide-photo-tools">${tideBtn('lifephoto:'+((index+photos.length-1)%photos.length),'上一张')}${tideBtn('lifephoto:'+((index+1)%photos.length),'下一张')}</nav>${tideBtn('photos','返回缩略图')}`);}
 return tideFrame('相册 / 生活照片',`<div class="tide-album">${photos.map((p,i)=>`<button data-tide-view="lifephoto:${i}"><img src="images/memories/${p.file}.jpg" alt="${p.alt}"><span>${escapeHTML(p.name)}</span></button>`).join('')}</div><p class="tide-muted">${tideDevices[tide.device].date.slice(0,4)} 年 / ${photos.length} 个文件 / 本站怀旧创作配图，不是人物真实照片。备注和时间均为虚构生活记录。</p>`);
}
function tideAlbum(){if(tide.device!=='black')return tideLifeAlbum();if(tideView.startsWith('photo:')){const id=tideView.split(':')[1];if(!['pier','gate','window'].includes(id))return tideHome();tideMark(id);const titles={pier:'DSC0018.JPG',gate:'DSC0028.JPG',window:'DSC0038.JPG'};const times={pier:'03:09',gate:'03:17',window:'03:42'};return tideFrame(titles[id],`<figure class="tide-photo ${tideView.includes('zoom')?'zoomed':''}"><img src="images/tide/${id}.svg" alt="${id==='pier'?'雾中的防波堤与灯塔':id==='gate'?'堤下混凝土墙上的深色检修门':'夜里关着的房间窗户'}" data-tide-photo></figure><div class="tide-photo-tools"><button data-tide-zoom>放大 / 还原</button>${tideBtn('back:'+id,'照片背面')}${tideBtn('meta:'+id,'文件信息')}</div><nav class="tide-photo-tools">${['pier','gate','window'].map((x,i)=>tideBtn('photo:'+x,String(i+1))).join('')}</nav>${tideBtn('photos','返回缩略图')}`);}
if(tideView.startsWith('back:')){if(tideView==='back:gate')tideMark('back');return tideFrame('照片备注',`<article class="tide-photo-back"><p>${tideView==='back:gate'?'门把手下面有一道旧划痕。浪退得最远时才能站到这里。——许舟':'没有写名字。纸角记着：别把白天的照片和晚上的混在一起。'}</p></article>${tideBtn('photo:'+tideView.split(':')[1],'翻回照片')}`);}
if(tideView.startsWith('meta:')){const id=tideView.split(':')[1];return tideFrame('文件信息',`<article><p>DSC00${id==='gate'?'28':id==='pier'?'18':'38'}.JPG</p><p>2008年10月18日 ${id==='gate'?'03:17':id==='pier'?'03:09':'03:42'}</p><p>设备：N73 / 本机存储卡</p><p>备注来自游戏剧情，非真实定位。</p></article>${tideBtn('photo:'+id,'返回照片')}`);}
return tideFrame('相册 / 存储卡',`<div class="tide-album">${['pier','gate','window'].map((id,i)=>`<button data-tide-view="photo:${id}"><img src="images/tide/${id}.svg" alt="${['防波堤','检修门','房间窗户'][i]}"><span>DSC00${i+1}8.JPG</span></button>`).join('')}</div><p class="tide-muted">3个文件 / 拍摄顺序</p>`);}
function tideBrowser(){if(tide.device!=='black')return tideFrame('浏览器 / 最近访问',`<article><p>${tide.device==='silver'?'吉他中国 / 二手效果器交流':'摄影社 / 毕业合照上传说明'}</p><p>${tide.device==='silver'?'长途汽车时刻表 / 周六末班车':'同学录 / 六月最后一次签到'}</p></article>`);
if(tideView==='web:tide'){tideMark('timetable');return tideFrame('海岸观测站 / 缓存',`<article class="tide-web"><h3>10月18日 潮位记录</h3><p>灯塔外侧：禁止通行。堤下旧检修门：仅退潮时露出，维修后已封闭。</p><table><tr><th>时间</th><th>记录</th></tr><tr><td>00:52</td><td>高潮</td></tr><tr><td>03:17</td><td>当晚最低潮位</td></tr><tr><td>06:41</td><td>回升</td></tr></table><p>站长：有游客反映门后有人敲击。请勿靠近，可能为松动构件。此表为虚构剧情数据，不可用于出行。</p></article>${tideBtn('browser','返回历史')}`);}
if(tideView==='web:404')return tideFrame('网页无法显示',`<article><h3>404 / 文件不存在</h3><p>echo-board.local/upload/low-water/right.wav</p><p>缓存摘要：不是重复播放。第二遍开始，里面会有人学你说话。</p><small>缓存时间 10月18日 03:26</small></article>${tideBtn('browser','返回历史')}`);
return tideFrame('浏览器',`<nav class="tide-photo-tools">${tideBtn('browser','历史记录')}${tideBtn('bookmarks','书签')}</nav><div class="tide-list">${tideBtn('web:ordinary','10-17　天气预报 / 小雨')}${tideBtn('web:tide','10-18　海岸观测站 / 潮位表')}${tideBtn('web:404','10-18　下载完成 / right.wav')}${tideBtn('forum','10-18　回声采集 / 器材与现场')}</div>${tideView==='web:ordinary'?'<article><p>夜间有雨。别忘了给录音机套防水袋。</p></article>':''}`);}
function tideForum(){if(tide.device!=='black')return tideFrame('我的论坛',`<article><h3>${tide.device==='silver'?'地下乐队排练室':'毕业摄影交流'}</h3><p>${tide.device==='silver'?'【求助】贝斯接电脑底噪太大 / 最后回复昨天':'【晒图】六班的毕业照 / 最后回复6月5日'}</p><p>一切都很普通。这个旧账号的主人，似乎只是认真过着自己的生活。</p></article>`);
if(tideView==='forum:post'){tideMark('forum');return tideFrame('回声采集 / 器材与现场',`<article class="tide-forum"><h3>【外采】海边的底噪里，有一段不属于海的声音</h3><small>楼主：听潮的人　10月17日</small><p>不是观鸟。我想留下一些没人注意过的环境声音。灯塔那边风太大，昨晚换到了堤下面，门缝里很安静。</p><hr><small>2楼 / 声卡坏了</small><p>先查串音和回授。为什么最后八秒像有人在学你呼吸？</p><hr><small>3楼 / 听潮的人　已编辑</small><p>那时候我没有开口。潮最低的时候，门外才有地方站。</p><hr><small>4楼 / 阿巡</small><p>别再传了。你说那句是以后才会说的，到底什么意思？</p><hr><small>管理员</small><p>音频暂不可下载。保留文字，等待楼主补充说明。</p></article>${tideBtn('community','返回版面')}`);}
return tideFrame('回声采集 BBS',`<div class="tide-list">${tideBtn('forum:ordinary','[器材] N73怎么避免风噪？')}${tideBtn('forum:post','[外采] 海边的底噪里… (4)')}${tideView==='forum:ordinary'?'<article><p>旧耳机上的海绵也能挡一点风。别为了录音跑到危险的地方。</p></article>':''}</div>`);}
function tideRecorder(){return tideFrame('本机录音',`<article><b>海堤_1018.wav</b><p>00:12 / 16kHz / 右声道导出</p><audio controls preload="none" src="audio/tide-original.wav" data-tide-recording aria-label="潮声收藏者原创环境音"></audio><small>原创合成海浪示意音；剧情人声以文字转录呈现，无突然巨响。播放完可查看文件附记；静音也可读完整转录。</small>${tideBtn('transcript','转录 / 文件附记')}</article>${tideView==='transcript'?`<article class="tide-wrong"><p>[浪声，远处三次敲击]</p><p>许舟：我已经回到房间了。</p><p>[四秒后，同一句话，声音离话筒更近]</p><p>附记：第一遍我没说话。短信草稿是回来以后才写的。</p></article>`:''}`);}
function tideJudge(owner,habit,place,time,ending){if(tide.device!=='black')return '这部手机的记录对不上这张旧纸。先放回桌上吧。';if(!['qq','gate','back','forum','timetable','recording'].every(k=>tide.seen.includes(k)))return '你还有无法解释的矛盾。现在下结论，似乎太早了。';if(owner!=='xu'||habit!=='field'||place!=='gate'||time!=='0317')return '这份记述和手机里留下的痕迹还不能互相印证。';if(!['sealed','played'].includes(ending))return '你还没决定怎样处理这份录音。';tide.solved=true;tide.ending=ending;tideSave();return ending==='sealed'?'你写下许舟的名字，把存储卡装进纸袋。窗外只有雨声。关机前，收件箱多了一句：“谢谢你没有再放第二遍。”你没有打开它。':'你留下了第二遍播放的记录。浪声停了，三下敲击从游戏里的窗外传来。屏幕亮起：“你终于知道，我喜欢收藏什么了。”第一篇完。';}
function tideJournal(){if(tide.device!=='black')return tideFrame('随手记',`<p>这部手机里，记着另一个普通人的生活。</p><form data-tide-notes><textarea name="notes" aria-label="我的潮声调查笔记" maxlength="1200">${escapeHTML(tide.notes)}</textarea><button>保存笔记</button></form>`);return tideFrame('随手记',`<p>桌边有一张没写完的纸。你可以先记下来，不急着解释。</p><form data-tide-notes><textarea name="notes" aria-label="我的潮声调查笔记" maxlength="1200" placeholder="我注意到…">${escapeHTML(tide.notes)}</textarea><button>保存笔记</button></form><details ${tideFeedback||tide.solved?'open':''}><summary>整理这部手机的最后一页</summary>${tideFeedback?`<p role="status" class="tide-result">${escapeHTML(tideFeedback)}</p>`:''}${tide.solved?`<p>已封存结局：${tide.ending==='sealed'?'没有播放第二遍':'第二遍'}</p>`:`<form data-tide-finish><label>机主<select name="owner"><option value="">尚不确定</option><option value="xu">许舟</option><option value="xun">阿巡</option><option value="unknown">陌生游客</option></select></label><label>他在收集什么<select name="habit"><option value="">尚不确定</option><option value="birds">鸟鸣</option><option value="field">环境声音</option><option value="travel">旅行照片</option></select></label><label>最后一次外采地点<select name="place"><option value="">尚不确定</option><option value="tower">灯塔外侧</option><option value="gate">堤下旧检修门</option><option value="room">自己的房间</option></select></label><label>那晚的时间（四位）<input name="time" maxlength="4" inputmode="numeric" pattern="[0-9]{4}" required></label><label>怎样处理录音<select name="ending"><option value="sealed">封存，不再播放</option><option value="played">在故事里留下第二遍播放记录</option></select></label><button>写下我的判断</button></form>`}</details><button data-tide-reset>${tideResetArmed?'确认重读（清除本篇进度）':'重读本篇'}</button>${tide.solved?'<p class="tide-wrong">故事结束，手机里的日常仍然可以继续。结局不证明怪谈真实发生。</p>':''}`);}
const tideNativeScreen=phoneScreen,tideEntranceBase=renderPhoneEntrance;
renderPhoneEntrance=function(){return `<section class="tide-entry"><small>新故事 · 原创离线解谜</small><h2>潮声收藏者</h2><p>旧手机里留下的，不只有联系人。</p><button data-tide-start>打开收藏架</button>${tide.active?'<button data-tide-resume>继续上次那部手机</button>':''}</section>`+tideEntranceBase();};
phoneScreen=function(){if(!tide.active)return tideNativeScreen();if(tideView==='shelf')return tideShelf();if(tideView==='journal')return tideJournal();if(phoneState.app==='home')return tideHome();if(phoneState.app==='sms')return tideSms();if(phoneState.app==='qq')return tideQQ();if(phoneState.app==='photos')return tideAlbum();if(phoneState.app==='browser')return tideBrowser();if(phoneState.app==='community')return tideForum();if(phoneState.app==='music'&&['recorder','transcript'].includes(tideView))return tideRecorder();if(phoneState.app==='music'&&tide.device!=='black')return tideNativeScreen();if(phoneState.app==='music')return `<div class="tide-music-entry">${tideBtn('recorder','海堤_1018.wav / 本机录音')}${tideBtn('shelf','收藏架')}</div>`+tideNativeScreen();return tideNativeScreen();};
function tideOpenDevice(id){if(!Object.hasOwn(tideDevices,id))return false;tide.notebooks[tide.device]=tide.notes;tide.notes=tide.notebooks[id]||'';tide.active=true;tide.device=id;tideView='';tideFeedback='';mysteryPanel='';phoneState.model=tideDevices[id].model;phoneState.app='home';date=tideDevices[id].date;deskEntered=true;tideSave();savePhone();navigate({type:'home'},false);return true;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-tide-start],[data-tide-resume],[data-tide-device],[data-tide-view],[data-tide-leave],[data-tide-zoom],[data-tide-reset],[data-tide-reply]');if(!b)return;e.preventDefault();if(b.dataset.tideReply){tideChatReply(b.dataset.tideReply);refreshPhone();document.querySelector('.tide-chat-choices')?.scrollIntoView?.({block:'nearest'});return;}if(b.hasAttribute('data-tide-reset')){if(!tideResetArmed){tideResetArmed=true;return refreshPhone();}tide.seen=[];tide.solved=false;tide.ending='';tide.replied=false;tide.draft='';tideFeedback='';tideResetArmed=false;tideView='';phoneState.app='home';tideSave();return refreshPhone();}if(b.hasAttribute('data-tide-resume'))return tideOpenDevice(tide.device);if(b.hasAttribute('data-tide-start')){dialog('桌上的旧手机',tideShelf());return;}if(b.dataset.tideDevice){document.querySelector('#modal')?.close();return tideOpenDevice(b.dataset.tideDevice);}if(b.hasAttribute('data-tide-leave')||b.dataset.tideView==='native'){tide.active=false;tideView='';tideSave();document.querySelector('#modal')?.close();return navigate({type:'home'},false);}if(b.hasAttribute('data-tide-zoom')){document.querySelector('.tide-photo')?.classList.toggle('zoomed');return;}const v=b.dataset.tideView;tideView=v;if(v==='sms')phoneState.app='sms';if(v==='qq'||v.startsWith('qq:'))phoneState.app='qq';if(v==='photos'||/^(photo|back|meta|lifephoto|lifeback|lifemeta):/.test(v))phoneState.app='photos';if(['browser','bookmarks'].includes(v)||v.startsWith('web:'))phoneState.app='browser';if(['community','forum'].includes(v)||v.startsWith('forum:'))phoneState.app='community';if(['recorder','transcript'].includes(v)){phoneState.app='music';if(v==='transcript')tideMark('recording');}refreshPhone();});
document.addEventListener('click',e=>{if(!tide.active)return;if(e.target.closest('[data-phone-app],[data-desk-open],[data-system-launch]'))tideView='';},true);
document.addEventListener('submit',e=>{if(!e.target.matches('[data-tide-compose],[data-tide-qq],[data-tide-notes],[data-tide-finish]'))return;e.preventDefault();const f=new FormData(e.target);if(e.target.matches('[data-tide-compose]')){tide.draft=String(f.get('message')||'').slice(0,100);tide.replied=true;}else if(e.target.matches('[data-tide-qq]'))return;else if(e.target.matches('[data-tide-notes]')){tide.notes=String(f.get('notes')||'').slice(0,1200);tide.notebooks[tide.device]=tide.notes;toast('笔记已留在本机');}else tideFeedback=tideJudge(f.get('owner'),f.get('habit'),f.get('place'),String(f.get('time')||''),f.get('ending'));tideSave();refreshPhone();});
document.addEventListener('ended',e=>{if(e.target.matches?.('[data-tide-recording]')){tideMark('recording');toast('录音已结束，文件附记可阅读');}},true);
// The desk frames the fiction; ordinary entertainment still uses the existing apps.
const tideWorkbenchBase=renderWorkbench,tideSelectBase=phoneSelectApp,tideInstalledBase=installedSystemApps;
installedSystemApps=function(){if(!tide.active)return tideInstalledBase();return ['sms','qq','photos','browser','community','music','games','books'].map(id=>systemApps.find(a=>a.id===id)).filter(Boolean);};
phoneSelectApp=function(app){if(tide.active)tideView='';return tideSelectBase(app);};
renderWorkbench=function(){if(!tide.active)return tideWorkbenchBase();return `<div class="handset-mobile-tools"><button data-tide-view="shelf">桌上的手机</button><button data-pocket-expand>⛶ 放大 / 退出</button><button data-phone-app="home">功能表</button></div><section class="tide-workbench"><aside class="tide-desk"><small>收藏日记 / ${tideDevices[tide.device].date.slice(0,4)}</small><h1>${tideDevices[tide.device].title}</h1><p>${tideDevices[tide.device].source}</p><p>有些东西不属于你。<br>但把它们关掉以前，你想知道它们为什么还留在这里。</p><button data-phone-app="home">回到手机功能表</button><button data-tide-view="shelf">换一部收藏机</button><button data-tide-view="journal">翻开桌边的随手记</button><button data-tide-view="native">普通游玩 / 退出故事</button><small>原创虚构怪谈。无自动声音；录音需主动播放。</small></aside><section class="home-phone-preview">${renderPhoneLab()}</section></section>`;};

for(const app of phoneApps)if(app[0]==='photos')app[1]='相册';
